// Tone Zone originals, second series: designs not inspired by any brand, in the Tone Zone "studio" design
// language (anodised aluminium, recessed control deck, engraved type, an accent stripe per family – see
// gfx/forms-tz.js) plus a few playful enclosures (orb, cassette / reel, synth slab).
import { K, SEL, TOG, BTN, FOOT, LED, SCREEN, SLIDER, TREADLE, ten, db, ms } from './helpers.js';
import { TZ, AMP, CAB, k, preampPair } from './builders.js';

// ---- enclosure families
const ST = (o) => TZ(Object.assign({ form: 'tz2-studio' }, o)); // studio stomp (+ bypass footswitch / LED)
const ORB = (o) => TZ(Object.assign({ form: 'tz2-orb' }, o));
const TAPE = (o) => TZ(Object.assign({ form: 'tz2-cassette' }, o));
const SLAB = (o) => TZ(Object.assign({ form: 'tz2-scope' }, o));
const TREAD = (o) => TZ(Object.assign({ form: 'tz2-treadle', noStd: true }, o));
const art = (stripe, extra = {}) => Object.assign({ stripe }, extra);
const DRIVE = art('band'), MODA = art('diag'), TIME = art('top'), STUDIO = art('left'), PITCH = art('twin');

// compact jack labels (the long A (MONO) / B names collide with the knob decks)
const STEREO = { ins: ['IN L', 'IN R'], outs: ['OUT L', 'OUT R'] };
const MONO_TO_ST = { ins: ['IN'], outs: ['OUT L', 'OUT R'] };
const st = (v) => (v > 0 ? '+' : '') + Math.round(v) + ' st';
const dbK = (p, label, o = {}) => K(p, label, Object.assign({ min: -24, max: 12, def: 0, display: db }, o));
const hz = (p, label, min, max, def) => K(p, label, { min, max, def, curve: 'log', unit: 'Hz' });
const NOTES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];

// ---- amps / cabs: TZ tolex + anodised panel + accent pinstripe
const TZAMP = (o) => AMP(Object.assign({ form: 'tz2-amp', baseForm: 'amp', brand: 'Tone Zone', ref: 'Tone Zone original', logoFont: "'Oswald', sans-serif", logoSize: 24, knob: 'chrome', grille: 'black' }, o, { color: o.tolex }));
const TZCAB = (o) => CAB(Object.assign({ form: 'tz2-cab', baseForm: 'cab', brand: 'Tone Zone', ref: 'Tone Zone original', logoFont: "'Oswald', sans-serif", logoSize: 15, logoColor: '#e9ecf3', stereoPorts: { ins: ['INPUT'], outs: ['MIC 1', 'MIC 2'] } }, o, { color: o.tolex || '#1b1d22' }));

const looperFoot = (label, ev, hold, o = {}) => FOOT(Object.assign({ label, action: 'event', event: ev, hold }, o));

